2372		if opts != nil && opts.Size > 0 {
2373			f.connMu.Lock()
2374			f.meta.Opts.Size = opts.Size
2375			if f.meta.Res != nil && !f.hasKnownSize() {
2376				f.setResourceSizeLocked(0, false)
2377			}
2378			f.connMu.Unlock()
2379		}
2380		// Patch request info
2381		if req != nil {
2382			if req.URL != "" {
2383				f.meta.Req.URL = req.URL
2384				// Clear redirect URL when URL is changed, so new requests use the new URL
2385				f.updateRedirectURL("")
2386			}
2387			if req.Extra != nil {
2388				if err := base.ParseReqExtra[fhttp.ReqExtra](req); err != nil {
2389					return err
2390				}
2391				patchExtra := req.Extra.(*fhttp.ReqExtra)
2392				// Merge Extra fields instead of replacing entirely
2393				if f.meta.Req.Extra == nil {
2394					f.meta.Req.Extra = &fhttp.ReqExtra{}
2395				}
2396				existingExtra := f.meta.Req.Extra.(*fhttp.ReqExtra)
2397				// Update Method only if non-empty
2398				if patchExtra.Method != "" {
2399					existingExtra.Method = patchExtra.Method
2400				}
2401				// Update Body only if non-empty
2402				if patchExtra.Body != "" {
2403					existingExtra.Body = patchExtra.Body
2404				}
2405				// Merge Headers: existing keys are overwritten, new keys are added
2406				if patchExtra.Header != nil {
2407					if existingExtra.Header == nil {
2408						existingExtra.Header = make(map[string]string)
2409					}
2410					for k, v := range patchExtra.Header {
2411						existingExtra.Header[k] = v
2412					}
2413				}
2414			}
2415			// Merge Labels: existing keys are overwritten, new keys are added
2416			if req.Labels != nil {
2417				if f.meta.Req.Labels == nil {
2418					f.meta.Req.Labels = make(map[string]string)
2419				}
2420				for k, v := range req.Labels {
2421					f.meta.Req.Labels[k] = v
2422				}
2423			}
2424			if req.Proxy != nil {
2425				f.meta.Req.Proxy = req.Proxy
2426			}
