	pieceMapReady := false
	peers := make([]*base.PeerStats, 0)
	if f.torrent != nil {
		stats = f.torrent.Stats()
		pieceMap, pieceMapReady = buildBTPieceMap(f.torrent)
		peers = buildBTPeers(f.torrent)
	} else {
		stats = torrent.TorrentStats{}
